{% doc %}
  Fulldev UI accordion styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-accordion.css' | asset_url | stylesheet_tag }}

/* The data-slot accordion, and the same parts on native <details> and <summary>, which open
   without JavaScript. */
[data-slot='accordion'] {
  display: flex;
  flex-direction: column;
  width: 100%;
}
[data-slot='accordion-item']:not(:last-child) {
  border-bottom: 1px solid var(--border);
}
.accordion__heading {
  font: inherit;
  letter-spacing: var(--tracking-normal);
}
[data-slot='accordion-trigger'] {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: calc(var(--spacing) * 4);
  width: 100%;
  padding-block: calc(var(--spacing) * 4);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.43;
  text-align: left;
  list-style: none;
  outline: none;
}
summary[data-slot='accordion-trigger']::-webkit-details-marker {
  display: none;
}
[data-slot='accordion-trigger']:hover {
  text-decoration: underline;
}
[data-slot='accordion-trigger']:focus-visible {
  border-color: var(--ring);
  box-shadow: var(--focus-ring);
}
[data-slot='accordion-trigger'] > .icon {
  width: calc(var(--spacing) * 4);
  height: calc(var(--spacing) * 4);
  margin-left: auto;
  color: var(--muted-foreground);
  transition: rotate 200ms;
}
[data-slot='accordion-item'][data-state='open'] [data-slot='accordion-trigger'] > .icon,
details[open] > [data-slot='accordion-trigger'] > .icon {
  rotate: 180deg;
}
[data-slot='accordion-content'] {
  overflow: hidden;
  font-size: 0.875rem;
}
[data-slot='accordion'] [data-slot='accordion-content'] {
  height: var(--accordion-panel-height);
  transition: height 200ms ease;
}
[data-slot='accordion-content'][data-starting-style],
[data-slot='accordion-content'][data-ending-style] {
  height: 0;
}
[data-slot='accordion-content-inner'] {
  padding-bottom: calc(var(--spacing) * 4);
}
